#include <bits/stdc++.h>
using namespace std;

int isVowel(char ch)
{
    if(ch == 'a' || ch == 'e' || ch == 'i' || ch == 'o' || ch == 'u')
    return 1;

    if(ch == 'A' || ch == 'E' || ch == 'I' || ch == 'O' || ch == 'U')
    return 1;

    return 0;
}

int subString(string s, int n)
{
    long long count=0;
    for (int i = 0; i < n; i++)
    {
       if(isVowel(s[i]))
       count += n-i;
    }
    return count%10003;          
}

int solve(string A) 
{	
    return subString(A, A.length());    
}

 
int main()
{
	string st = "";
    int res = solve(st);
    cout << res;
    return 0;
}
 
 

